how-generative-models-learn.code:
from collections import Counter

examples = ["forest"] * 5 + ["coast"] * 3 + ["city"] * 2
counts = Counter(examples)
learned = {name: n / len(examples) for name, n in counts.items()}
sunset = {"forest": 0.2, "coast": 0.7, "city": 0.1}

def sample(probabilities, draw):
    assert 0 <= draw < 1
    assert abs(sum(probabilities.values()) - 1) < 1e-9
    cumulative = 0.0
    for name, probability in probabilities.items():
        cumulative += probability
        if draw < cumulative:
            return name

print("Learned:", learned)
for draw in [0.35, 0.72, 0.95]:
    print(f"r={draw:.2f}: plain={sample(learned, draw)}, "
          f"sunset={sample(sunset, draw)}")

multimodal-ai.code:
import math

def cosine(a, b):
    dot = sum(x*y for x, y in zip(a, b))
    norm_a = math.sqrt(sum(x*x for x in a))
    norm_b = math.sqrt(sum(y*y for y in b))
    if norm_a == 0 or norm_b == 0:
        raise ValueError("A zero vector has no cosine direction.")
    return dot / (norm_a * norm_b)

text = [0.8, 0.6]
images = {"A": [0.6, 0.8], "B": [-0.6, 0.8], "C": [-0.8, -0.6]}
scores = {name: cosine(text, vector) for name, vector in images.items()}
for name, score in scores.items():
    print(f"Image {name}: {score:.2f}")
print("Top candidate:", max(scores, key=scores.get))

