cases = [
    {"id": "A", "private_data": True, "evidence": True, "high_impact": False},
    {"id": "B", "private_data": False, "evidence": False, "high_impact": False},
    {"id": "C", "private_data": False, "evidence": True, "high_impact": True},
    {"id": "D", "private_data": False, "evidence": True, "high_impact": False},
]

def route(case):
    if case["private_data"]:
        return "BLOCK and escalate privacy review"
    if not case["evidence"]:
        return "REQUEST supporting evidence"
    if case["high_impact"]:
        return "REQUIRE specialist approval"
    return "SEND draft to editor"

for case in cases:
    print(case["id"], "->", route(case))
assert all(route(case) != "AUTO-PUBLISH" for case in cases)

building-genai-apps.code:
import json

approved_actions = {("Asha", "send minutes")}
responses = [
    '{"decisions": "ship Friday", "actions": []}',
    '{"decisions": [], "actions": [{"owner": "Ravi", "task": "send minutes"}]}',
    '{"decisions": [], "actions": [{"owner": "Asha", "task": "send minutes"}]}',
]

def validate(raw):
    try:
        data = json.loads(raw)
    except json.JSONDecodeError:
        return "REJECT: invalid JSON"
    if not isinstance(data, dict):
        return "REJECT: object required"
    if not all(isinstance(data.get(k), list) for k in ["decisions", "actions"]):
        return "REJECT: required fields must be lists"
    for action in data["actions"]:
        if not isinstance(action, dict):
            return "REJECT: action must be an object"
        owner, task = action.get("owner"), action.get("task")
        if not isinstance(owner, str) or not isinstance(task, str):
            return "REJECT: owner and task must be strings"
        if (owner, task) not in approved_actions:
            return "REVIEW: action lacks approved evidence"
    return "DRAFT READY: request human approval"

for response in responses:
    print(validate(response))
